package com.videokit.d1input;
import java.io.*;import java.util.concurrent.*;import java.util.function.*;import java.util.concurrent.atomic.*;import com.videokit.spike.c14.*;
import static com.videokit.d1input.InputSinkCheck.*;
public class IndependentResponseOrderCheck {
 static final String TOKEN="controlled_ready_token";static int scenarios;
 static void finishBounded(TemporaryOutput s)throws Exception{long end=System.nanoTime()+TimeUnit.SECONDS.toNanos(2);while(true){try{s.finishOriginalCallbacks();return;}catch(IOException e){need(e.getMessage().equals("OUTPUT_ORIGINAL_PENDING"),"only stable pending allowed");if(System.nanoTime()>end)throw e;Thread.sleep(2);}}}
 static class Host extends MemSink {
  final boolean apply;CompletableFuture<String> response=new CompletableFuture<>();CompletableFuture<Void> abortResponse;CompletableFuture<SinkCoordinator.Status> queryResponse;CountDownLatch queryEntered=new CountDownLatch(1);int queryRPC;boolean trueAuthority;SinkCoordinator.Status badAuthority;
  Host(boolean applied){apply=applied;}
  public CompletionStage<String> markReady(String id){need(id.equals(task),"exact task");if(apply)super.markReady(id);else readies++;return response;}
  public CompletionStage<Void> abort(String id){CompletionStage<Void> actual=super.abort(id);return abortResponse==null?actual:abortResponse;}
  public CompletionStage<SinkCoordinator.Status> query(String id){queryRPC++;queryEntered.countDown();return queryResponse!=null?queryResponse:super.query(id);}
  public SinkCoordinator.Status originalTerminalStatus(String id){need(id.equals(task),"same original authority task");if(badAuthority!=null)return badAuthority;return trueAuthority?new SinkCoordinator.Status(status,status==SinkCoordinator.HostState.READY?TOKEN:null):new SinkCoordinator.Status(SinkCoordinator.HostState.UNKNOWN,null);}
 }
 static void prepared(TemporaryOutput s,Host h)throws Exception{IndependentFixCheck.finishAndValidate(s,h);rejected(s::markReady,"OUTPUT_READY_UNKNOWN");need(!h.response.isDone()&&h.originalOperationsReturned(),"actual host work returned but original response unanswered");}
 static void note(String key,TemporaryOutput s){System.out.println("OBSERVE "+key+" keeper="+TemporaryOutput.retained()+" "+s.state());}
 static void pass(String key){scenarios++;System.out.println("PASS independent_order "+key);}
 static void original(boolean normal)throws Exception{
  Host h=new Host(normal);TemporaryOutput s=new TemporaryOutput(h,false,WORKER,80);
  try{prepared(s,h);need(!s.abort()&&!s.observeOriginal()&&!s.returned(),"original response still unanswered");rejected(s::finishOriginalCallbacks,"OUTPUT_ORIGINAL_PENDING");note("original_RESPONSE_PENDING_normal="+normal,s);h.response.complete(normal?TOKEN:"contradictory_late_token");await(s::originalReadyResponseReceived);
   if(normal){need(s.readyAcknowledged()&&s.originalReadyResponseAccepted()&&!s.state().contains("abortedAck=true"),"same token late ACK accepted");finishBounded(s);}
   else{need(!s.readyAcknowledged()&&!s.originalReadyResponseAccepted()&&s.originalReadyResponseRejection().equals("CONFLICT_WITH_ABORTED")&&s.state().contains("readyResponseSucceeded=true")&&s.state().contains("abortedAck=true"),"transport success distinct from adoption");rejected(s::finishOriginalCallbacks,"OUTPUT_ORIGINAL_PENDING");need(TemporaryOutput.retained()==1,"default UNKNOWN holds conflict");h.trueAuthority=true;finishBounded(s);}
   need(s.returned()&&h.readies==1&&h.aborts==1&&h.queryRPC==1&&s.firstFailure().equals("OUTPUT_READY_UNKNOWN"),"same originals/RPCs/first error preserved");note("original_RETURNED_normal="+normal,s);pass(normal?"B07_same_token_late_ACK":"B06_late_ACK_conflict_with_ABORTED");
  }finally{h.response.complete(normal?TOKEN:"contradictory_late_token");h.trueAuthority=true;if(!s.returned())finishBounded(s);}
 }
 static void ackBeforeQuery()throws Exception{
  Host h=new Host(true);h.queryResponse=new CompletableFuture<>();TemporaryOutput s=new TemporaryOutput(h,false,WORKER,300);AtomicReference<Throwable> error=new AtomicReference<>();Thread caller=new Thread(()->{try{s.abort();}catch(Throwable t){error.set(t);}},"tester-same-abort-caller");
  try{prepared(s,h);caller.start();need(h.queryEntered.await(2,TimeUnit.SECONDS),"original query entered");h.response.complete(TOKEN);await(s::originalReadyResponseReceived);need(s.readyAcknowledged()&&s.originalReadyResponseAccepted(),"READY ACK before QUERY answer");h.queryResponse.complete(new SinkCoordinator.Status(SinkCoordinator.HostState.ABORTED,null));caller.join(2000);need(!caller.isAlive()&&(error.get()==null||error.get() instanceof IOException),"same actual caller returns stable result");
   need(s.readyAcknowledged()&&!s.state().contains("abortedAck=true")&&s.state().contains("terminalProtocolUnknown=true")&&!s.returned(),"later conflicting query cannot override READY");rejected(s::finishOriginalCallbacks,"OUTPUT_ORIGINAL_PENDING");h.trueAuthority=true;finishBounded(s);need(h.queryRPC==1&&h.aborts==1&&h.readies==1,"no correction RPC");note("ACK_BEFORE_CONFLICTING_QUERY",s);pass("ACK_before_QUERY_response");
  }finally{h.response.complete(TOKEN);h.queryResponse.complete(new SinkCoordinator.Status(SinkCoordinator.HostState.READY,TOKEN));if(caller.getState()!=Thread.State.NEW)caller.join(2000);h.trueAuthority=true;if(!s.returned())finishBounded(s);}
 }
 static void badAuthorityBeforeAck()throws Exception{
  Host h=new Host(true);TemporaryOutput s=new TemporaryOutput(h,false,WORKER,80);
  try{prepared(s,h);need(!s.abort()&&s.readyAcknowledged(),"accurate original QUERY READY first");h.badAuthority=new SinkCoordinator.Status(SinkCoordinator.HostState.ABORTED,null);need(!s.abort()&&s.state().contains("terminalProtocolUnknown=true"),"contradictory readonly before late ACK");h.badAuthority=null;h.response.complete(TOKEN);await(s::originalReadyResponseReceived);need(s.originalReadyResponseAccepted()&&s.readyAcknowledged()&&s.state().contains("terminalProtocolUnknown=true"),"matching ACK cannot erase other source conflict");rejected(s::finishOriginalCallbacks,"OUTPUT_ORIGINAL_PENDING");h.trueAuthority=true;finishBounded(s);need(h.queryRPC==1&&h.aborts==1&&h.readies==1,"accurate original readonly resolves without RPC");note("BAD_AUTHORITY_THEN_SAME_ACK",s);pass("conflicting_authority_then_same_ACK");}finally{h.response.complete(TOKEN);h.badAuthority=null;h.trueAuthority=true;if(!s.returned())finishBounded(s);}
 }
 static class ObserverFuture extends CompletableFuture<String> {
  final CountDownLatch inObserver=new CountDownLatch(1),leaveObserver=new CountDownLatch(1);volatile Thread actual;
  public CompletableFuture<String> whenComplete(BiConsumer<? super String,? super Throwable> action){return super.whenComplete((v,e)->{action.accept(v,e);actual=Thread.currentThread();inObserver.countDown();try{leaveObserver.await();}catch(InterruptedException x){Thread.currentThread().interrupt();throw new CompletionException(x);}});}
 }
 static void abortPendingThenFailedReady(boolean cancelled)throws Exception{
  Host h=new Host(false);h.abortResponse=new CompletableFuture<>();TemporaryOutput s=new TemporaryOutput(h,false,WORKER,80);
  try{prepared(s,h);need(!s.abort()&&h.aborts==1&&h.queryRPC==0&&!s.returned(),"original ABORT has happened but its ACK pending, no QUERY");
   h.response.completeExceptionally(cancelled?new CancellationException("private-late-response-cancel"):new IOException("private-late-response-failed"));await(s::originalReadyResponseReceived);
   need(!s.readyAcknowledged()&&!s.originalReadyResponseAccepted()&&s.originalReadyResponseRejection().equals("ORIGINAL_ACK_FAILED")&&s.state().contains("readyResponseSucceeded=false"),"late failure facts kept, not business rollback proof");
   need(!s.observeOriginal()&&h.queryRPC==0,"unanswered original ABORT still holds response gate");rejected(s::finishOriginalCallbacks,"OUTPUT_ORIGINAL_PENDING");note("ABORT_PENDING_READY_LATE_FAILED_cancelled="+cancelled,s);h.abortResponse.complete(null);
   long end=System.nanoTime()+TimeUnit.SECONDS.toNanos(2);while(!s.returned()){try{s.abort();}catch(IOException e){need(e.getMessage().equals("OUTPUT_ORIGINAL_PENDING"),"stable original return gate");}if(System.nanoTime()>end)throw new AssertionError("same original abort/query failed to converge");if(!s.returned())Thread.sleep(2);}
   need(h.readies==1&&h.aborts==1&&h.queryRPC==1&&s.state().contains("abortedAck=true")&&!s.readyAcknowledged()&&s.firstFailure().equals("OUTPUT_READY_UNKNOWN"),"accurate QUERY terminal, original calls once and sticky first error");pass(cancelled?"ABORT_ACK_pending_then_READY_late_cancel":"ABORT_ACK_pending_then_READY_late_failure");
  }finally{h.response.completeExceptionally(new IOException("cleanup-original-response"));h.abortResponse.complete(null);h.trueAuthority=true;if(!s.returned())finishBounded(s);}
 }
 static void actualObserverTail()throws Exception{
  Host h=new Host(true);ObserverFuture response=new ObserverFuture();h.response=response;TemporaryOutput s=new TemporaryOutput(h,false,WORKER,80);CountDownLatch clientIdle=new CountDownLatch(1),endClient=new CountDownLatch(1);Thread client=new Thread(()->{response.complete(TOKEN);clientIdle.countDown();try{endClient.await();}catch(InterruptedException e){Thread.currentThread().interrupt();}},"tester-long-lived-client-delivery");
  try{prepared(s,h);need(!s.abort(),"accurate QUERY first with response in flight");client.start();need(response.inObserver.await(2,TimeUnit.SECONDS),"same actual SDK observer action reached its tail");need(response.isDone()&&s.readyAcknowledged()&&s.originalReadyResponseAccepted()&&response.actual==client&&!s.returned(),"response and accepted facts do not prove observer return");rejected(s::finishOriginalCallbacks,"OUTPUT_ORIGINAL_PENDING");need(s.state().contains("scopedObserversReturned=false")&&TemporaryOutput.retained()==1,"hold same observer returned stage");note("SDK_OBSERVER_TAIL_actualThread="+client.getId(),s);response.leaveObserver.countDown();need(clientIdle.await(2,TimeUnit.SECONDS),"same observer physically returned");finishBounded(s);need(client.isAlive()&&s.returned(),"external client may stay alive after original observer returned");pass("actual_observer_tail_vs_long_lived_client");}finally{response.leaveObserver.countDown();response.complete(TOKEN);endClient.countDown();if(client.getState()!=Thread.State.NEW)client.join(2000);if(!s.returned())finishBounded(s);need(!client.isAlive(),"same external client joined after test");}
 }
 static class RegisterFuture extends CompletableFuture<String> {
  final CountDownLatch inMethod=new CountDownLatch(1),leaveMethod=new CountDownLatch(1);volatile Thread actual;
  public CompletableFuture<String> whenComplete(BiConsumer<? super String,? super Throwable> action){CompletableFuture<String> dependent=super.whenComplete(action);actual=Thread.currentThread();inMethod.countDown();try{leaveMethod.await();}catch(InterruptedException e){Thread.currentThread().interrupt();throw new CompletionException(e);}return dependent;}
 }
 static void zeroCounterWorker()throws Exception{
  RegisterFuture original=new RegisterFuture();original.complete(TOKEN);int[] rpc={0};SinkCoordinator c=new SinkCoordinator("exact_task",new SinkCoordinator.Host(){public CompletionStage<String> markReady(String id){rpc[0]++;return original;}public CompletionStage<Void> abort(String id){return CompletableFuture.completedFuture(null);}public CompletionStage<SinkCoordinator.Status> query(String id){return CompletableFuture.completedFuture(new SinkCoordinator.Status(SinkCoordinator.HostState.READY,TOKEN));}},80);c.start();c.validating();
  try{need(c.finalizeReady(true).equals(TOKEN)&&original.inMethod.await(2,TimeUnit.SECONDS),"original actual coordinator action done but registration method held");need(c.pendingCallbacks()==0&&!c.originalResponsesCompleted()&&original.actual.isAlive(),"zero count not physical original worker return");rejected(()->c.awaitOriginalCallbacks(80),"OUTPUT_ORIGINAL_PENDING");Thread actual=original.actual;System.out.println("OBSERVE independent_zero_counter actualWorker="+actual.getId()+" name="+actual.getName()+" alive="+actual.isAlive()+" pendingCount="+c.pendingCallbacks());original.leaveMethod.countDown();actual.join(2000);c.awaitOriginalCallbacks(1000);need(!actual.isAlive()&&c.originalCallbacksReturned()&&rpc[0]==1,"same SDK-created worker actually joined");pass("zero_counter_same_actual_SDK_worker_tail");}finally{original.leaveMethod.countDown();c.awaitOriginalCallbacks(1000);need(c.originalCallbacksReturned(),"coordinator original thread cleanup");}
 }
 public static void main(String[] args)throws Exception{System.out.println("ORIGIN="+TemporaryOutput.class.getProtectionDomain().getCodeSource().getLocation());original(false);original(true);ackBeforeQuery();badAuthorityBeforeAck();actualObserverTail();zeroCounterWorker();abortPendingThenFailedReady(false);abortPendingThenFailedReady(true);need(TemporaryOutput.retained()==0&&HostInputFactory.admittedSources()==0,"all owners returned");System.out.println("DONE independentOrderScenarios="+scenarios+" originalThreadsAndObserversReturned=true sourceKeepers0 outputKeepers0");}
}
